// Standalone C++17; input n, colors, then n-1 edges.
#include <bits/stdc++.h>
using namespace std;
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);
    int n;cin>>n;vector<int> c(n);for(int &x:c)cin>>x;
    vector<vector<int>> g(n);for(int i=1,u,v;i<n;++i){cin>>u>>v;--u;--v;g[u].push_back(v);g[v].push_back(u);}
    vector<int> par(n,-1),order{0};par[0]=0;
    for(int i=0;i<n;++i)for(int v:g[order[i]])if(v!=par[order[i]]){par[v]=order[i];order.push_back(v);}
    vector<map<int,int>> bag(n);vector<int> mx(n);vector<long long> sum(n),ans(n);
    auto add=[&](int u,int color,int delta){int f=(bag[u][color]+=delta);
        if(f>mx[u]){mx[u]=f;sum[u]=color;}else if(f==mx[u])sum[u]+=color;};
    for(int i=n-1;i>=0;--i){int u=order[i];add(u,c[u],1);
        for(int v:g[u])if(par[v]==u){
            if(bag[u].size()<bag[v].size()){bag[u].swap(bag[v]);swap(mx[u],mx[v]);swap(sum[u],sum[v]);}
            for(auto [color,count]:bag[v])add(u,color,count);bag[v].clear();
        }ans[u]=sum[u];
    }for(auto x:ans)cout<<x<<' ';
}

// Standalone C++17; input n,k and values in [1,n].
#include <bits/stdc++.h>
using namespace std;
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);
    int n,k;cin>>n>>k;vector<int>a(n);for(int&x:a)cin>>x;
    vector<int> f(n+1);int L=0,R=-1;long long cost=0,INF=(1LL<<60);
    auto add=[&](int i){cost+=f[a[i]]++;};
    auto del=[&](int i){cost-=--f[a[i]];};
    auto query=[&](int l,int r){while(L>l)add(--L);while(R<r)add(++R);
        while(L<l)del(L++);while(R>r)del(R--);return cost;};
    vector<long long> prev(n+1,INF),cur(n+1,INF);prev[0]=0;
    for(int t=1;t<=k;++t){fill(cur.begin(),cur.end(),INF);
        function<void(int,int,int,int)> solve=[&](int l,int r,int ol,int orr){
            if(l>r)return;int m=(l+r)/2,best=-1;
            for(int j=ol;j<=min(m-1,orr);++j){long long v=prev[j]+query(j,m-1);
                if(v<cur[m]){cur[m]=v;best=j;}}
            solve(l,m-1,ol,best);solve(m+1,r,best,orr);
        };solve(t,n,t-1,n-1);prev.swap(cur);
    }cout<<prev[n];
}

vector<int> twoSum(vector<int>& a,int target){
    unordered_map<int,int> seen;
    for(int i=0;i<(int)a.size();++i){
        auto it=seen.find(target-a[i]);
        if(it!=seen.end()) return {it->second,i};
        seen[a[i]]=i;
    }
    return {};
}

vector<vector<int>> levelOrder(TreeNode* root){
    vector<vector<int>> out;if(!root)return out;
    queue<TreeNode*> q;q.push(root);
    while(!q.empty()){int size=q.size();vector<int> row;
        while(size--){auto u=q.front();q.pop();row.push_back(u->val);
            if(u->left)q.push(u->left);if(u->right)q.push(u->right);}
        out.push_back(row);
    }return out;
}

int longestCommonSubsequence(string a,string b){
    int n=a.size(),m=b.size();vector<vector<int>> d(n+1,vector<int>(m+1));
    for(int i=1;i<=n;++i)for(int j=1;j<=m;++j)
        d[i][j]=a[i-1]==b[j-1]?d[i-1][j-1]+1:max(d[i-1][j],d[i][j-1]);
    return d[n][m];
}

int rob(vector<int>& a){
    int before=0,previous=0;
    for(int x:a){int now=max(previous,before+x);before=previous;previous=now;}
    return previous;
}

int numIslands(vector<vector<char>>& g){
    if(g.empty())return 0;int n=g.size(),m=g[0].size(),ans=0;
    int dx[]={1,-1,0,0},dy[]={0,0,1,-1};
    for(int i=0;i<n;++i)for(int j=0;j<m;++j)if(g[i][j]=='1'){
        ++ans;queue<pair<int,int>> q;q.push({i,j});g[i][j]='0';
        while(!q.empty()){auto [x,y]=q.front();q.pop();
            for(int d=0;d<4;++d){int a=x+dx[d],b=y+dy[d];
                if(a>=0&&a<n&&b>=0&&b<m&&g[a][b]=='1'){g[a][b]='0';q.push({a,b});}}
        }
    }return ans;
}

ListNode* reverseList(ListNode* head){
    ListNode* prev=nullptr;
    while(head){auto next=head->next;head->next=prev;prev=head;head=next;}
    return prev;
}

vector<int> maxSlidingWindow(vector<int>& a,int k){
    deque<int> q;vector<int> out;
    for(int i=0;i<(int)a.size();++i){
        while(!q.empty()&&q.front()<=i-k)q.pop_front();
        while(!q.empty()&&a[q.back()]<=a[i])q.pop_back();
        q.push_back(i);if(i>=k-1)out.push_back(a[q.front()]);
    }return out;
}

int lengthOfLongestSubstring(string s){
    vector<int> last(256,-1);int l=0,best=0;
    for(int r=0;r<(int)s.size();++r){
        unsigned char c=s[r];l=max(l,last[c]+1);
        last[c]=r;best=max(best,r-l+1);
    }return best;
}

int lengthOfLIS(vector<int>& a){
    vector<int> tails;for(int x:a){auto p=lower_bound(tails.begin(),tails.end(),x);
        if(p==tails.end())tails.push_back(x);else *p=x;
    }return tails.size();
}

int searchInsert(vector<int>& a,int target){
    int l=0,r=a.size();while(l<r){int m=l+(r-l)/2;
        if(a[m]<target)l=m+1;else r=m;
    }return l;
}

vector<vector<int>> permute(vector<int>& a){
    vector<vector<int>> out;vector<int> path,used(a.size());
    function<void()> dfs=[&]{
        if(path.size()==a.size()){out.push_back(path);return;}
        for(int i=0;i<(int)a.size();++i)if(!used[i]){
            used[i]=1;path.push_back(a[i]);dfs();path.pop_back();used[i]=0;
        }
    };dfs();return out;
}

int subarraySum(vector<int>& a,int k){
    unordered_map<long long,long long> f;f[0]=1;
    long long s=0,ans=0;
    for(int x:a){s+=x;ans+=f[s-k];++f[s];}
    return (int)ans;
}
